#define CACHE_BLOCK_SIZE 64
#define CACHE_WAYS 4

struct CacheLine {
    uint8_t valid;       // V-bit
    uint8_t dirty;       // D-bit (for Write-back)
    uint64_t tag;        // Address identifier
    uint8_t data[CACHE_BLOCK_SIZE];
    uint32_t lru_counter; // Replacement policy metric
};

// 64-bit Address Decomposition Example (6-bit Offset, 10-bit Index)
typedef union {
    uint64_t full_address;
    struct {
        uint64_t offset : 6;
        uint64_t index  : 10;
        uint64_t tag    : 48;
    };
} MemoryAddress;
